import * as React from 'react';
import { testEngine } from "../../api.js";
import { useI18n } from "../../i18n.js";
/**
 * Render one failure.
 *
 * The transport decides what kind of failure it is; the page only supplies the
 * words.
 */
function describeFailure(failure, t) {
    switch (failure.kind) {
        case 'auth':
            return t(failure.messageKey);
        case 'timeout':
            return t('test.timeout');
        case 'cancelled':
            return '';
        case 'host':
            return failure.message;
    }
}
export function useEngineTesting({ enabledEngineIds, engineConfigs, keyInputs, open, }) {
    const { t } = useI18n();
    const [query, setQuery] = React.useState('');
    const [isSearching, setIsSearching] = React.useState(false);
    const [engineStates, setEngineStates] = React.useState({});
    const [hasSearched, setHasSearched] = React.useState(false);
    const abortControllerRef = React.useRef(null);
    // Abort any in-flight test requests when modal closes
    React.useEffect(() => {
        if (!open && abortControllerRef.current) {
            abortControllerRef.current.abort();
            abortControllerRef.current = null;
        }
    }, [open]);
    // Single engine test runner
    const runTestForEngine = React.useCallback(async (engineId, searchQuery, signal) => {
        setEngineStates((prev) => ({
            ...prev,
            [engineId]: { state: 'loading' },
        }));
        const engineConf = engineConfigs[engineId];
        const tempKey = keyInputs[engineId];
        const outcome = await testEngine({
            engineId,
            query: searchQuery,
            maxResults: 5,
            engineConfig: engineConf,
            tempApiKey: tempKey !== undefined ? tempKey : undefined,
        }, signal);
        if (outcome.ok && outcome.result) {
            setEngineStates((prev) => ({
                ...prev,
                [engineId]: {
                    state: 'success',
                    durationMs: outcome.durationMs,
                    result: outcome.result,
                },
            }));
            return;
        }
        // A cancelled call leaves the card alone: the modal is closing.
        if (outcome.failure?.kind === 'cancelled')
            return;
        setEngineStates((prev) => ({
            ...prev,
            [engineId]: {
                state: 'error',
                durationMs: outcome.durationMs,
                error: outcome.failure ? describeFailure(outcome.failure, t) : '',
            },
        }));
    }, [engineConfigs, keyInputs, t]);
    // Run test across all enabled engines
    const handleSearchAll = React.useCallback(async (onSuccessStart) => {
        const trimmed = query.trim();
        if (!trimmed || enabledEngineIds.length === 0 || isSearching)
            return;
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }
        const ctrl = new AbortController();
        abortControllerRef.current = ctrl;
        setIsSearching(true);
        setHasSearched(true);
        if (onSuccessStart)
            onSuccessStart();
        // Set initial loading state for all enabled engines
        const initialStatus = {};
        for (const id of enabledEngineIds) {
            initialStatus[id] = { state: 'loading' };
        }
        setEngineStates(initialStatus);
        try {
            await Promise.allSettled(enabledEngineIds.map((id) => runTestForEngine(id, trimmed, ctrl.signal)));
        }
        finally {
            setIsSearching(false);
        }
    }, [query, enabledEngineIds, isSearching, runTestForEngine]);
    // Single engine retry
    const handleRetrySingle = React.useCallback((engineId, onBeforeRetry) => {
        const trimmed = query.trim();
        if (!trimmed)
            return;
        if (onBeforeRetry)
            onBeforeRetry();
        runTestForEngine(engineId, trimmed);
    }, [query, runTestForEngine]);
    // Calculate summary counts
    const summary = React.useMemo(() => {
        const total = enabledEngineIds.length;
        let success = 0;
        let failed = 0;
        for (const id of enabledEngineIds) {
            const st = engineStates[id];
            if (st?.state === 'success')
                success++;
            if (st?.state === 'error')
                failed++;
        }
        return { total, success, failed };
    }, [enabledEngineIds, engineStates]);
    return {
        query,
        setQuery,
        isSearching,
        hasSearched,
        engineStates,
        summary,
        runTestForEngine,
        handleSearchAll,
        handleRetrySingle,
    };
}
